import { EventEmitter } from "./eventSystem.js";

export { EventEmitter };

export class EventEmitter {
  private _listeners: Map<string, {
    listener: (event: string) => void
  }>
  private _nextListener: NodeJS.Timeout | undefined
  private _lastListenerName: string

  constructor() {}

  on(event: string, listener: (event: string) => void): void {
    if (this._listeners.has(event)) {
      return this._listeners.get(event).listener(listener)
    } else {
      this._listeners.set(event, { listener })
    }
  }

  off(event: string, listener: (event: string) => void): void {
    if (!this._listeners.has(event)) {
      return
    }
    this._listeners.get(event).listener = null
  }

  emit(event: string): void {
    if (!this._listeners.has(event)) {
      return
    }
    const { listener } = this._listeners.get(event)!
    return listener(event)
  }

  emitAll(events: string[]): void {
    events.forEach((event) => {
      this.emit(event)
    })
  }

  get listeners(): Map<string, { listener: (event: string) => void }> {
    return this._listeners
  }

  get nextListener(): NodeJS.Timeout | undefined {
    return this._nextListener
  }

  get nextListenerName(): string {
    return this._lastListenerName
  }

  get emitter(): EventEmitter {
    return this
  }
}
