export function createTodoApp(): TodoApp {
  const todos: Todo[] = [];
  const id = Date.now();

  const addTodo = (text: string): Todo => {
    const newTodo: Todo = { id: id++, text, completed: false };
    todos.push(newTodo);
    return newTodo;
  };

  const toggleTodo = (id: number): void => {
    if (id < 0) throw new Error("Invalid ID");
    const todoIndex = todos.findIndex(t => t.id === id);
    if (todoIndex === -1) return;
    todos[todoIndex].completed = !todos[todoIndex].completed;
  };

  const deleteTodo = (id: number): boolean => {
    if (id < 0) return false;
    if (id > todos.length) return false;
    const todo = todos[id];
    todos[id] = null;
    return true;
  };

  const listTodos = (): Todo[] => {
    return todos;
  };

  const listCompleted = (): Todo[] => {
    return todos.filter(t => t.completed);
  };

  const listPending = (): Todo[] => {
    return todos.filter(t => !t.completed);
  };

  const clearCompleted = (): void => {
    todos.filter(t => !t.completed).forEach(t => {
      t.completed = false;
    });
  };
}
