export type OneTimeCallback<T> = (event: string, ...args: any[]) => T;

export function createEventEmitter<Listener, ReturnValue = void>(
  listener: Listener
): EventEmitter<Listener, ReturnValue> {
  const oneTimeListeners = new Map<string, OneTimeCallback<ReturnValue>>();
  const listeners = new Map<string, OneTimeCallback<ReturnValue>>();

  return {
    fire(event: string, ...args: any[]): ReturnValue {
      for (const callback of listeners.values()) {
        const result = callback(event, ...args);
        if (result instanceof OneTimeCallback) {
          oneTimeListeners.set(event, result);
        }
      }
      return result;
    },

    on(event: string, listener: Listener<ReturnValue>): void {
      listeners.set(event, listener);
    },

    off(event: string, listener?: OneTimeCallback<ReturnValue>): void {
      const toRemove = listeners.get(event) || [];
      if (toRemove.length === 0) return;
      toRemove[0]();
    },

    get listeners(event: string): OneTimeCallback<ReturnValue> {
      return listeners.get(event) || null;
    }
  };
}
