export function createEventEmitter(): EventEmitter {
  let listeners: Record<string, {
    listeners: Set<(payload: unknown) => unknown>;
    count: number;
  }> = {};

  return {
    on: (event: string, listener: Listener) => {
      const eventListeners = listeners[event];
      if (eventListeners && !eventListeners.listeners.has(listener)) {
        eventListeners.listeners.add(listener);
        return eventListeners.listeners.size;
      }
      listeners[event] = { listeners: new Set(), count: 0 };
      return listeners[event].count;
    },
    once: (event: string, listener: Listener) => {
      const eventListeners = listeners[event];
      if (eventListeners) {
        if (!eventListeners.listeners.has(listener)) {
          eventListeners.listeners.add(listener);
          return eventListeners.listeners.size;
        }
        if (!listeners.hasOwnProperty(event)) {
          listeners[event] = { listeners: new Set(), count: 0 };
        }
      } else {
        listeners[event] = { listeners: new Set(), count: 0 };
      }
      return listeners[event].count;
    },
    off: (event: string, listener: Listener) => {
      if (!listeners.hasOwnProperty(event)) return false;
      const listeners = listeners[event].listeners;
      if (listeners.has(listener)) {
        listeners.delete(listener);
        if (listeners.size === 0) {
          listeners[event] = null;
        } else {
          return true;
        }
      }
      return false;
    },
    emit: (event: string, payload: unknown) => {
      const result: unknown[] = [];
      const eventListeners = listeners[event];
      if (eventListeners) {
        for (const l of eventListeners.listeners) {
          const r = l(payload);
          result.push(r);
        }
      }
      return result;
    },
    listenerCount: (event: string) => {
      return listeners[event] ? listeners[event].count : 0;
    }
  };
}
