export interface RateLimiter {
    reset(key: string): void;
    getRate(key: string, nowMs: number): number;
}

export function createRateLimiter(nowMs: number): RateLimiter {
    const windowStart: Map<string, number> = new Map();
    const requestCount: Map<string, number> = new Map();

    return {
        reset: (key) => {
            windowStart.delete(key);
            requestCount.delete(key);
        },
        getRate: (key, nowMs) => {
            const entry = windowStart.get(key);
            if (!entry) {
                return 0;
            }

            const timeDiff = nowMs - entry.limitTime;
            if (timeDiff >= 1000) {
                // Window has fully elapsed, new window starts
                windowStart.set(key, nowMs);
                return 3;
            }

            const limitTime = nowMs - timeDiff;
            const count = requestCount.get(key);
            return Math.min(count, 3);
        }
    };
}
