export function createRateLimiter(): {
  acquire(key: string, nowMs: number): boolean;
  reset(key: string): void;
} {
  const state = new Map<string, { count: number; lastWindowStart: number }>();

  function acquire(key: string, nowMs: number): boolean {
    const limit = 3;
    const windowDuration = 1000;

    const s = state.get(key);
    let count = 0;
    let lastWindowStart = 0;

    if (s) {
      count = s.count;
      lastWindowStart = s.lastWindowStart;
    }

    if (nowMs >= lastWindowStart + windowDuration) {
      state.set(key, { count: 1, lastWindowStart: nowMs });
      return true;
    }

    if (count >= limit) {
      return false;
    }

    state.set(key, { count: count + 1, lastWindowStart });
    return true;
  }

  function reset(key: string): void {
    state.delete(key);
  }

  return {
    acquire,
    reset
  };
}
