interface RateLimiter {
  allow(key: string, nowMs: number): boolean
  remaining(key: string, nowMs: number): number
  reset(key: string): void
}

const LIMIT = 3;
const WINDOW_MS = 1000;

export function createRateLimiter(): RateLimiter {
  const stateMap = new Map<string, { windowStart: number; count: number }>();

  return {
    allow: (key: string, nowMs: number): boolean => {
      const state = stateMap.get(key);

      if (!state) {
        stateMap.set(key, {
          windowStart: nowMs,
          count: 0,
        });
        return true;
      }

      // Check boundary reset
      if (nowMs - state.windowStart >= WINDOW_MS) {
        state.windowStart = nowMs;
        state.count = 0;
      }

      // Increment success counter and check limit
      if (state.count < LIMIT) {
        state.count++;
        return true;
      }
      return false;
    },
    remaining: (key: string, nowMs: number): number => {
      const state = stateMap.get(key);
      if (!state) {
        return LIMIT;
      }

      // Check boundary reset
      if (nowMs - state.windowStart >= WINDOW_MS) {
        state.windowStart = nowMs;
        state.count = 0;
      }

      // Return remaining quota (non-negative)
      return Math.max(0, LIMIT - state.count);
    },
    reset: (key: string): void => {
      stateMap.delete(key);
    }
  };
}
