interface TtlCache {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
  get(key: string, nowMs: number): unknown
  has(key: string, nowMs: number): boolean
  delete(key: string): boolean
  size(nowMs: number): number
  clear(): void
}

export function createTtlCache(): TtlCache {
  const cache = new Map<string, { value: unknown; expiresAt: number }>()

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
      const actualTtl = ttlMs ?? 1000
      const expiresAt = nowMs + actualTtl
      cache.set(key, { value, expiresAt })
    },

    get(key: string, nowMs: number): unknown {
      const entry = cache.get(key)
      if (!entry || nowMs >= entry.expiresAt) return undefined
      return entry.value
    },

    has(key: string, nowMs: number): boolean {
      const entry = cache.get(key)
      if (!entry) return false
      return nowMs < entry.expiresAt
    },

    delete(key: string): boolean {
      const exists = cache.has(key)
      cache.delete(key)
      return exists
    },

    size(nowMs: number): number {
      let count = 0
      for (const [key, { value, expiresAt }] of cache.entries()) {
        if (nowMs < expiresAt) {
          count++
        }
      }
      return count
    },

    clear(): void {
      cache.clear()
    }
  }
}
