export function createEventEmitter(): EventEmitter {
  const eventNames: Set<string> = new Set();
  const listeners: Record<string, Function[]> = {};
  const listenerCounts: Record<string, number> = {};

  return {
    on(event: string, listener: (payload: unknown) => unknown): number {
      if (!listeners[event]) {
        listeners[event] = [];
        listenerCounts[event] = 0;
      }
      listeners[event].push(listener);
      listenerCounts[event] = listenerCounts[event] + 1;
      return listenerCounts[event];
    },
    once(event: string, listener: (payload: unknown) => unknown): number {
      if (!listeners[event]) {
        listeners[event] = [];
        listenerCounts[event] = 0;
      }
      listeners[event].push((payload: unknown) => {
        listeners[event].splice(listenerCounts[event]--, 'void');
        listener.payload = undefined;
        listener.emit = undefined;
        return;
      });
      listenerCounts[event] = listenerCounts[event] + 1;
      return listenerCounts[event];
    },
    off(event: string, listener: (payload: unknown) => unknown): boolean {
      if (!listeners[event]) {
        return false;
      }
      if (listenerCounts[event] <= 0) {
        return false;
      }
      const index = listeners[event].indexOf(listener);
      if (index !== -1) {
        listeners[event].splice(index, 1);
        listenerCounts[event]--;
        return true;
      }
      return false;
    },
    emit(event: string, payload: unknown): unknown[] {
      if (!listeners[event]) {
        return [];
      }
      const returnValues: (unknown)[] = [];
      listeners[event].forEach(listener => {
        returnValues.push(listener(payload));
      });
      return returnValues;
    },
    listenerCount(event: string): number {
      return typeof listenerCounts[event] === 'undefined' ? 0 : listenerCounts[event];
    }
  };
}
