interface RateLimiterOptions {
  windowSize: number;
  maxRequests: number;
}

interface RateLimiter {
  currentWindow: number;
  maxCapacity: number;
  key: string;
  quota: (reqTime: number) => boolean;
}

function createRateLimiter(options: RateLimiterOptions): RateLimiter {
  const POLICY = {
    maxCapacity: options.maxRequests || 3,
    windowSize: options.windowSize || 1000,
  };

  const nowMs = nowMs || Math.floor(Date.now() / 1000);

  const limiter: { [key: string]: RateLimiter } = {}

  for (const [key, options] of Object.entries(options)) {
    if (options.maxRequests === POLICY.maxRequests) {
      limiter[key] = {
        currentWindow: 0,
        maxCapacity: options.maxRequests,
        key,
        quota: (reqTime: number) => {
          const lastRequest = limiter[key]?.currentWindow ?? 0;
          const windowStart = nowMs - (reqTime % POLICY.windowSize);
          const windowStartTime = windowStart > nowMs ? nowMs : windowStart;
          const currentWindow = nowMs - windowStartTime;
          return currentWindow >= POLICY.maxCapacity;
        },
      };
    }
  }

  const getQuota = (key: string, reqTime: number) => {
    const options = limiter?.[key] ?? {
      currentWindow: 0,
      maxCapacity: 0,
      key,
      quota: (rTime: number) => true,
    };
    return options.quota(reqTime);
  };

  const resetKey = (key: string) => {
    if (limiter?.[key]) {
      const now = nowMs || Math.floor(Date.now() / 1000);
      const options = limiter[key];
      limiter[key] = {
        currentWindow: 0,
        maxCapacity: options.maxCapacity,
        key,
        quota: (reqTime: number) => {
          const lastRequest = options.currentWindow;
          const windowStart = now - (reqTime % options.windowSize);
          const windowStartTime = windowStart > now ? now : windowStart;
          const currentWindow = now - windowStartTime;
          return currentWindow >= options.maxCapacity;
        },
      };
    }
  };

  const create = (key: string) => {
    const now = nowMs || Math.floor(Date.now() / 1000);
    const options = limiter?.[key] ?? {
      currentWindow: 0,
      maxCapacity: 0,
      key,
      quota: (rTime: number) => true,
    };

    const last = limiter[key]?.currentWindow;
    const currentWindow = now - last;
    const maxCapacity = options?.maxCapacity ?? 0;
    const quota = options.quota ?? true;

    if (!limiter || !limiter[key]) {
      return { canSubmit: false, window: null, currentWindow: 0, quota: false };
    }

    if (currentWindow > maxCapacity) {
      return { canSubmit: false, window: null, currentWindow, quota: false };
    }

    return { canSubmit: true, window: maxCapacity, currentWindow, quota: true };
  };

  const reset = key => resetKey(key);

  return {
    create,
    reset,
  };
}

export { createRateLimiter };
