export function createTodoApp(): {
  addTodo: (text: string) => { id: number; text: string; completed: false };
  getTodo: (id: number) => { id: number; text: string; completed: boolean } | undefined;
  toggleTodo: (id: number) => void;
  deleteTodo: (id: number) => boolean;
  listTodos: () => Array<{ id: number; text: string; completed: boolean }>;
  listCompleted: () => Array<{ id: number; text: string; completed: boolean }>;
  listPending: () => Array<{ id: number; text: string; completed: boolean }>;
  clearCompleted: () => void;
} {
  const todos = new Map<number, { id: number; text: string; completed: boolean }>();

  const getNextId = () => {
    const maxId = todos.size ? Math.max(...Array.from(todos.keys())) : 0;
    return maxId + 1;
  };

  const addTodo = (text: string) => {
    const id = getNextId();
    const todo = { id, text, completed: false };
    todos.set(id, todo);
    return todo;
  };

  const getTodo = (id: number) => {
    return todos.get(id);
  };

  const toggleTodo = (id: number) => {
    if (!todos.has(id)) return;
    todos.get(id)!.completed = !todos.get(id)!.completed;
  };

  const deleteTodo = (id: number) => {
    if (!todos.has(id)) return false;
    todos.delete(id);
    return true;
  };

  const listTodos = () => {
    return Array.from(todos.entries()).map(([id, todo]) => todo);
  };

  const listCompleted = () => {
    return Array.from(todos.values()).filter(todo => todo.completed);
  };

  const listPending = () => {
    return Array.from(todos.values()).filter(todo => !todo.completed);
  };

  const clearCompleted = () => {
    Array.from(todos.values()).forEach(todo => todo.completed = false);
  };
}
