export function createTtlCache() {
  const ttlMs = 1000
  const now: number = Date.now()

  const cache: Record<string, { value: unknown; expiresAt: number }> = {}

  function set(key: string, value: unknown, nowMs?: number, ttlMs?: number): void {
    const expiresAt = nowMs ?? now
    const updated = false
    if (nowMs !== undefined) {
      if (nowMs < expiresAt) {
        updated = true
      }
    }

    cache[key] = { value: value, expiresAt: expiresAt }

    if (updated) {
      // Remove stale entries on set
      for (const oldKey of Object.keys(cache)) {
        if (oldKey === key && !Object.values(cache)[oldKey].expiresAt > nowMs) {
          cache[oldKey] = null
        }
      }
    }
  }

  function get(key: string, nowMs?: number): unknown {
    const entry = cache[key]
    if (!entry) {
      return undefined
    }

    const now = nowMs ?? now
    if (now >= entry.expiresAt) {
      delete cache[key]
      return undefined
    }

    return entry.value
  }

  function has(key: string, nowMs?: number): boolean {
    const entry = cache[key]
    if (!entry || entry.expiresAt < nowMs) {
      return false
    }
    return true
  }

  function delete(key: string): boolean {
    const entry = cache[key]
    if (!entry || entry.expiresAt < nowMs) {
      return false
    }
    delete cache[key]
    return true
  }

  function size(nowMs?: number): number {
    let count = 0
    for (const [, entry] of Object.entries(cache)) {
      const now = nowMs ?? now
      if (now < entry.expiresAt) {
        count++
      }
    }
    return count
  }

  function clear(): void {
    cache = {}
  }

  return { set, get, has, delete, size, clear }
}
