export function createTtlCache(): TtlCache {
  const baseTtlMs = 1000;

  function set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
    const expiresAt = nowMs - ttlMs || nowMs - baseTtlMs;
    cache.set(key, { value, expiresAt, nowMs });
  }

  function get(key: string, nowMs: number): unknown {
    const entry = cache.get(key);
    if (!entry || entry.expiresAt <= nowMs) {
      return undefined;
    }
    return entry.value;
  }

  function has(key: string, nowMs: number): boolean {
    const entry = cache.get(key);
    if (!entry || entry.expiresAt <= nowMs) {
      return false;
    }
    return true;
  }

  function delete(key: string): boolean {
    const entry = cache.get(key);
    if (!entry) {
      return false;
    }
    const { value, expiresAt, nowMs } = entry;
    const newExpiresAt = nowMs + (ttlMs || baseTtlMs);
    cache.delete(key);
    if (value !== undefined) {
      // Need to update the cached value since we lost the original
      const existingEntry = get(key, nowMs);
      if (existingEntry) {
        set(key, value, nowMs, newExpiresAt);
      }
    }
    return true;
  }

  function size(nowMs: number): number {
    return cache.size(nowMs);
  }

  function clear(): void {
    cache.clear();
  }

  return cache;
}

const cache = {};
const ttlMs = 1000;

export { cache };
