```typescript
type ListenerCallback<T extends any[], R = any> = (...args: T) => R;

type NormalListener<T extends any[], R = any> = ListenerCallback<T> & { onCall: number };

type OneTimeListener<T extends any[], R = any> = ListenerCallback<T> & { onCall: number; isOneTime: true };

type Listener<T extends any[], R = any> = NormalListener<T> | OneTimeListener<T>;

interface ListenerData<T extends any[], R = any> {
  callback: ListenerCallback<T, R>;
  name: string; // optional for tracking
  onCall: number;
  isOneTime: boolean;
}

interface EventCallback<T extends any[], R = any> {
  on<K extends keyof T>(eventName: K, callback: ListenerCallback<T[K], R>, name?: string): void;
  off<K extends keyof T>(eventName: K, callback?: ListenerCallback<T[K]> | string): void;
  emit<K extends keyof T>(eventName: K, ...args: T[K]): R | void;
  once<K extends keyof T>(eventName: K, callback: ListenerCallback<T[K]}, name?: string): void;
}

function createEventEmitter<T extends Record<string, any[]>[]>(
  initialEvents?: T
): EventCallback<T[number]> {
  const listeners: Map<string, ListenerData<any[], any>[]> = new Map();

  function registerListener(eventName: string, listener: ListenerCallback<any[], any>, name?: string): void {
    if (!listeners.has(eventName)) {
      listeners.set(eventName, []);
    }

    const eventListeners = listeners.get(eventName)!;
    let exists = false;
    for (const i of eventListeners) {
      if (i.callback === listener) {
        exists = true;
        break;
      }
    }
    if (exists) return;

    eventListeners.push({
      callback: listener,
      name: name || eventName,
      onCall: eventListeners.length,
      isOneTime: false,
    });
  }

  function registerOneTimeListener(eventName: string, callback: ListenerCallback<any[], any>, name?: string): void {
    registerListener(eventName, callback, name);
  }

  function removeListener(eventName: string, callback: ListenerCallback<any[], any> | string): void {
    if (!listeners.has(eventName)) return;

    const eventListeners = listeners.get(eventName)!;
    const callbackType = typeof callback === 'string' ? callback : 'function';

    if (callbackType === 'function') {
      for (let i = 0; i < eventListeners.length; i++) {
        if (eventListeners[i].callback === callback) {
          eventListeners.splice(i, 1);
          break;
        }
      }
    } else {
      const eventName = callback as string;
      for (let i = 0; i < eventListeners.length; i++) {
        if (eventListeners[i].name === eventName) {
          eventListeners.splice(i, 1);
          break;
        }
      }
    }
  }

  function emitListeners(eventName: string, args: any[]): any[] {
    const eventListeners = listeners.get(eventName);
    if (!eventListeners || eventListeners.length === 0) return [];

    const results: any[] = [];
    for (const listener of eventListeners) {
      try {
        const result = listener.callback(...args);
        results.push(result);
      } catch (e) {
        results.push(e);
      }
    }
    return results;
  }

  if (initialEvents) {
    for (const eventName in initialEvents) {
      const events = initialEvents[eventName] as any[];
      for (const event of events) {
        const listener = (args: any[]) => {
          if (args.length > 0 && typeof event === 'function') {
            return event(...args);
          }
          return args.length > 0 ? args[0] : undefined;
        };
        registerListener(eventName, listener, eventName);
      }
    }
  }

  return {
    on: <K extends keyof T>(
      eventName: K,
      callback: ListenerCallback<T[K], any>,
      name?: string
    ): void => {
      registerListener(eventName as string, callback, name);
    },
    once: <K extends keyof T>(
      eventName: K,
      callback: ListenerCallback<T[K], any>,
      name?: string
    ): void => {
      registerOneTimeListener(eventName as string, callback, name);
    },
    off: <K extends keyof T>(
      eventName: K,
