function createEventEmitter<T extends Record<string, any[]>[]>(
  initialEvents?: T
): Emitter {
  const listeners = new Map<string, EmitterData[]>();
  const listenersByEventName: Record<string, EmitterData[]> = {};

  function addListener(
    eventName: string,
    callback: Function,
    name: string | undefined,
    isOneTime: boolean
  ): void {
    if (!listenersByEventName[eventName]) {
      listenersByEventName[eventName] = [];
    }
    listenersByEventName[eventName].push({
      callback,
      name: name || eventName,
      isOneTime,
    });
  }

  function removeListener(
    eventName: string,
    callback?: Function | string,
    isOneTime: boolean = false
  ): void {
    if (!listenersByEventName[eventName]) return;
    // Remove by callback reference if callback is provided
    if (callback && typeof callback === 'function') {
      const idx = listenersByEventName[eventName].findIndex(
        (d: EmitterData) => d.callback === callback
      );
      if (idx >= 0) listenersByEventName[eventName].splice(idx, 1);
    }
    // Remove by name if string is provided
    else if (callback && typeof callback === 'string') {
      const name = callback as string;
      for (let i = listenersByEventName[eventName].length - 1; i >= 0; i--) {
        if (listenersByEventName[eventName][i].name === name) {
          listenersByEventName[eventName].splice(i, 1);
          break;
        }
      }
    }
    // Default: remove one-time listeners if not specified
    else if (isOneTime) {
      const oneTimeList = listenersByEventName[eventName]?.filter(
        (d: EmitterData) => d.isOneTime && !d.callback
      ) || [];
      for (const data of oneTimeList) {
        // Remove from listeners map as well
        listeners.delete(data.name);
      }
    }
    else {
      // Remove all non-one-time listeners
      const indices: number[] = [];
      for (let i = 0; i < listenersByEventName[eventName]!.length; i++) {
        if (!listenersByEventName[eventName]![i].isOneTime) {
          indices.push(i);
        }
      }
      for (const idx of indices) {
        listenersByEventName[eventName]!.splice(idx, 1);
      }
    }
  }

  const on = (eventName: string, callback: Function, name?: string): void => {
    addListener(eventName, callback, name, false);
  };

  const once = (eventName: string, callback: Function, name?: string): void => {
    addListener(eventName, callback, name, true);
  };

  const emit = <T>(eventName: string | number, ...args: T): T => {
    const eventKey = typeof eventName === 'string'
      ? eventName
      : `${eventName}:` as string;
    const event = listeners.get<string>(eventKey);
    if (!event || event.length === 0) return undefined as T;
    for (const data of event) {
      try {
        data.callback(...args);
        // Check if one-time listener was called
        if (data.isOneTime) {
          const idx = event.indexOf(data);
          if (idx >= 0) event.splice(idx, 1);
