class EventEmitterImpl {
  private listeners: Map<string, Array<(payload: unknown) => unknown>> = new Map()
  private onceListeners: Array<{
    func: (payload: unknown) => unknown
    events: string[]
  }> = []
  private onceFired: Set<(payload: unknown) => unknown> = new Set()
  private onceIndex: Map<(unknown) => unknown, number> = new Map()
  private listenerOrderIndex: Map<string, Array<(unknown) => unknown>> = new Map()

  on(event: string, listener: (payload: unknown) => unknown): number {
    if (!this.listeners.has(event)) {
      this.listeners.set(event, [])
    }
    const list = this.listeners.get(event)
    list.push(listener)
    return list.length
  }

  once(event: string, listener: (payload: unknown) => unknown): number {
    if (this.onceListeners.find(l => l.func === listener)) {
      return this.onceListeners.length
    }
    this.onceListeners.push({ func: listener, events: [event] })
    return this.onceListeners.length
  }

  off(event: string, listener: (payload: unknown) => unknown): boolean {
    const list = this.listeners.get(event)
    if (list && !list.includes(listener)) {
      return false
    }
    this.listeners.forEach((listeners, eventName) => {
      const index = listeners.indexOf(listener)
      if (index !== -1) {
        listeners.splice(index, 1)
        return true
      }
    })
    return false
  }

  emit(event: string, payload: unknown): unknown[] {
    const results: unknown[] = []
    const listeners = this.listeners.get(event)

    listeners?.forEach(l => {
      const result = l(payload)
      results.push(result)
      const index = this.onceListeners.findIndex(l => l.func === l)
      if (index !== -1 && !onceFired.has(l.func)) {
        results.push(l(payload))
        onceFired.add(l.func)
        const eventToRemove = l.events.find(e => e === event)
        if (eventToRemove) {
          const index = listeners?.indexOf(l.func)
          if (index !== -1) {
            listeners.splice(index, 1)
          }
          onceFired.add(l.func)
        }
      }
    })
    return results
  }

  listenerCount(event: string): number {
    return this.listeners.get(event)?.length ?? 0
  }
}
