interface RateLimiter {
  allow(key: string, nowMs: number): boolean
  remaining(key: string, nowMs: number): number
  reset(key: string): void
}

function createRateLimiter(): RateLimiter {
  const limit = 3;
  const windowMs = 1000;
  const state = new Map<string, { windowStart: number; remaining: number }>();

  return {
    allow(key: string, nowMs: number): boolean {
      const keyState = state.get(key);

      // Check for boundary reset: if nowMs - windowStart >= windowMs, start a fresh window
      if (!keyState || nowMs - keyState.windowStart >= windowMs) {
        state.set(key, {
          windowStart: nowMs,
          remaining: limit
        });
      }

      // Check if we have quota left
      const stateAfterCheck = state.get(key);
      if (stateAfterCheck && stateAfterCheck.remaining > 0) {
        stateAfterCheck.remaining--;
        state.set(key, stateAfterCheck);
        return true;
      }

      return false;
    },

    remaining(key: string, nowMs: number): number {
      const keyState = state.get(key);

      // Check for boundary reset: if nowMs - windowStart >= windowMs, start a fresh window
      if (!keyState || nowMs - keyState.windowStart >= windowMs) {
        state.set(key, {
          windowStart: nowMs,
          remaining: limit
        });
      }

      // Return state if exists, otherwise full quota
      const stateAfterCheck = state.get(key);
      return stateAfterCheck ? stateAfterCheck.remaining : limit;
    },

    reset(key: string): void {
      state.delete(key);
    }
  };
}

export { createRateLimiter };
