    addTodo(text: string): { id: number, text: string, completed: boolean } {
      const newTodo = {
        id: state.nextId,
        text,
        completed: false,
      };
      state.todos.push(newTodo);
      state.nextId++;
      return newTodo;
    },

    getTodo(id: number): { id: number, text: string, completed: boolean } | undefined {
      const todo = state.todos.find((t) => t.id === id);
      return todo;
    },

