type Entry = {
  value: unknown;
  expiresAt: number;
};

type TtlCache = {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
  get(key: string, nowMs: number): unknown;
  has(key: string, nowMs: number): boolean;
  delete(key: string): boolean;
  size(nowMs: number): number;
  clear(): void;
};

class TtlCacheImpl {
  private entries: Map<string, Entry>;

  constructor() {
    this.entries = new Map();
  }

  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
    const effectiveTtl = ttlMs ?? 1000;
    this.entries.set(key, {
      value,
      expiresAt: nowMs + effectiveTtl,
    });
  }

  get(key: string, nowMs: number): unknown {
    const entry = this.entries.get(key);
    if (entry == null) {
      return undefined;
    }
    if (nowMs >= entry.expiresAt) {
      this.entries.delete(key);
      return undefined;
    }
    return entry.value;
  }

  has(key: string, nowMs: number): boolean {
    const entry = this.entries.get(key);
    if (entry == null) {
      return false;
    }
    return nowMs < entry.expiresAt;
  }

  delete(key: string): boolean {
    return this.entries.delete(key);
  }

  size(nowMs: number): number {
    let count = 0;
    for (const [key, entry] of this.entries.entries()) {
      if (nowMs < entry.expiresAt) {
        count++;
      }
    }
    return count;
  }

  clear(): void {
    this.entries.clear();
  }
}

export function createTtlCache(): TtlCache {
  return new TtlCacheImpl();
}
