export function createTtlCache(): TtlCache {
  const storage = new Map<string, { value: unknown; expiresAt: number }>();
  const DEFAULT_TTL = 1000;

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
      const effectiveTtlMs = ttlMs ?? DEFAULT_TTL;
      storage.set(key, {
        value,
        expiresAt: nowMs + effectiveTtlMs
      });
    },

    get(key: string, nowMs: number): unknown {
      if (!storage.has(key)) {
        return undefined;
      }
      const entry = storage.get(key);
      if (nowMs >= entry?.expiresAt) {
        storage.delete(key);
        return undefined;
      }
      return entry?.value;
    },

    has(key: string, nowMs: number): boolean {
      if (!storage.has(key)) {
        return false;
      }
      const entry = storage.get(key);
      return nowMs < entry?.expiresAt ?? false;
    },

    delete(key: string): boolean {
      const wasExists = storage.has(key);
      storage.delete(key);
      return wasExists;
    },

    size(nowMs: number): number {
      let count = 0;
      for (const [, { expiresAt }] of storage.entries()) {
        if (nowMs < expiresAt) {
          count++;
        }
      }
      return count;
    },

    clear(): void {
      storage.clear();
    }
