export function createRateLimiter(): RateLimiter {
  function process(key: string): boolean {
    const now = Date.now()
    const windowMs = 1000
    let keyStart = now
    if (windowMs > 0) {
      const elapsed = now - keyStart
      if (elapsed >= windowMs) {
        keyStart = now
      }
    }

    if (keyStart === windowStart) {
      keyStart = now
    }

    let allowed = false
    if (allow(key, now)) {
      if (remaining <= 0 || now - windowStart >= windowMs) {
        return false
      }
      remaining--
    }

    allowed = true
    windowStart = now
    if (elapsed >= windowMs) {
      windowStart = now
    }

    return allowed
  }

  const state: { key: string; windowStart: number; windowElapsed: number; elapsed: number; remaining: number }[] = []

  Object.entries(state).forEach(([key, value]) => {
    const { key, windowStart, windowElapsed, elapsed, remaining } = value
    state.push({
      key,
      windowStart,
      windowElapsed,
      elapsed: windowElapsed + elapsed,
      remaining: remaining
    })
  })

  return {
    allow: (key: string, nowMs: number) => {
      if (state.some(v => v.key === key)) {
        const { key, windowStart, windowElapsed, elapsed, remaining } = state.find(v => v.key === key)
        if (elapsed >= windowMs) {
          return false
        }
        const nextMs = nowMs - elapsed
        return nextMs >= 0
      }
      const { windowStart } = state[0]
      if (nowMs - windowStart >= windowMs) {
        state.shift()
        return false
      }
      return true
    },
    remaining: (key: string, nowMs: number): number => {
      const { key, windowStart, windowElapsed, elapsed, remaining } = state.find(v => v.key === key)
      if (state.length > 0 && remaining <= 0) {
        return 0
      }

      windowLast = nowMs - windowElapsed
      let nextMs = nowMs - windowLast
      let shouldReset = false

      if (windowLast === 0) {
        windowLast = nowMs
      } else {
        shouldReset = nextMs >= windowMs
        if (shouldReset) {
          state.shift()
        }
      }

      return nextMs >= 0 ? 1 : 0
    },
    reset: (key: string) => {
      state.forEach(v => if (v.key === key) state.push(v))
    }
  }
}

export default createRateLimiter

