  value: number;
  memory: number;
}

export interface CalculatorInterface {
  add: (val: number) => CalculatorInterface;
  subtract: (val: number) => CalculatorInterface;
  multiply: (val: number) => CalculatorInterface;
  divide: (val: number) => CalculatorInterface | null;
  clear: () => CalculatorInterface;
  result: () => number;
  memoryStore: () => CalculatorInterface;
  memoryAdd: () => CalculatorInterface;
  memoryClear: () => CalculatorInterface;
  memoryRecall: () => [number, number];
}

export function createCalculator(): CalculatorInterface {
  const state: CalculatorState = { value: 0, memory: 0 };

  return {
    add: (val: number) => {
      const stateCopy = { ...state };
      stateCopy.value = stateCopy.value + val;
      return stateCopy as CalculatorInterface;
    },
    subtract: (val: number) => {
      const stateCopy = { ...state };
      stateCopy.value = stateCopy.value - val;
      return stateCopy as CalculatorInterface;
    },
    multiply: (val: number) => {
      const stateCopy = { ...state };
      stateCopy.value = stateCopy.value * val;
      return stateCopy as CalculatorInterface;
    },
    divide: (val: number) => {
      const stateCopy = { ...state };
      if (val === 0) return null;
      stateCopy.value = stateCopy.value / val;
      return stateCopy as CalculatorInterface;
    },
    clear: () => {
      const stateCopy = { ...state };
      stateCopy.value = 0;
      return stateCopy as CalculatorInterface;
    },
    result: () => {
      return state.value;
    },
    memoryStore: () => {
      const stateCopy = { ...state };
      stateCopy.memory = stateCopy.memory + stateCopy.value;
      return stateCopy as CalculatorInterface;
    },
    memoryAdd: () => {
      const stateCopy = { ...state };
      stateCopy.memory = stateCopy.memory + stateCopy.value;
      return stateCopy as CalculatorInterface;
    },
    memoryClear: () => {
      const stateCopy = { ...state };
      stateCopy.memory = 0;
      stateCopy.value = 0;
      return stateCopy as CalculatorInterface;
    },
    memoryRecall: () => {
      return [state.memory, state.value];
    },
  };
