export class EventEmitter {
  private events = new Map<string, Array<Listener>>()

  on(event: string, listener: Listener): number {
    this.events.set(event, this.events.get(event) || []).push(listener)
    return this.events.get(event)?.length || 0
  }

  once(event: string, listener: Listener): number {
    this.events.set(event, this.events.get(event) || []).push(listener)
    return this.events.get(event)?.length || 0
  }

  off(event: string, listener: Listener): boolean {
    const registeredEvents = this.events.get(event)
    if (!registeredEvents) {
      return false
    }

    const index = registeredEvents.indexOf(listener)
    if (index === -1) {
      return false
    }

    registeredEvents.splice(index, 1)
    return true
  }

  emit(event: string, payload: unknown): unknown[] {
    const listeners = this.events.get(event)
    if (!listeners) {
      return []
    }

    return listeners.map(listener => listener(payload))
  }

  listenerCount(event: string): number {
    const listeners = this.events.get(event)
    return listeners ? listeners.length : 0
  }
}
