export function createRateLimiter(options: RateLimiterOptions): RateLimiter {
  return new RateLimiter(options);
}

export interface RateLimiterOptions {
  maxRequests: number;
  windowMs: number;
}

export interface RateLimiterState {
  [key: string]: { count: number; expires: number };
}

export class RateLimiter {
  private state: RateLimiterState;

  constructor(options: RateLimiterOptions) {
    this.state = {};
    const now = nowMs() / 1000;
    for (const key in options) {
      this.state[key] = {
        count: 0,
        expires: now + options.windowMs,
      };
    }
  }

  private nowMs(): number;
  private nowMs(): number {
    return Date.now();
  }

  private resetKey(key: string, nowMs: number): boolean {
    if (this.state[key]) {
      delete this.state[key];
      return true;
    }
    return false;
  }

  private shouldReject(key: string, nowMs: number): boolean {
    const state = this.state[key];
    if (!state || nowMs >= state.expires) {
      state.count = this.maxRequests;
      state.expires = (nowMs + this.maxRequests * this.maxRequests) * 1000;
      return false;
    }
    return true;
  }

  key(): string {
    return Math.random().toString(36).slice(2, 10);
  }

  async request(): Promise<boolean> {
    const key = this.key();
    const now = nowMs();

    if (this.shouldReject(key, now)) {
      return false;
    }

    state.count += 1;

    if (nowMs >= state.expires) {
      state.count = 0;
      state.expires = nowMs + this.maxRequests * this.maxRequests;
      return true;
    }

    return true;
  }

  resetAll(): void {
    for (const [key] of Object.keys(this.state)) {
      this.resetKey(key, nowMs());
    }
  }

  reset(key: string): void {
    if (this.resetKey(key, nowMs())) {
      delete this.state[key];
    }
  }
}
