export function createRateLimiter(): {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
} {
  const limit = 3;
  const windowMs = 1000;

  function getOrCreateWindow(key: string): { windowStart: number; quota: number } {
    if (!key) {
      throw new Error("Key cannot be empty");
    }

    const now = Date.now();
    if (now - window[key] < windowMs) {
      window[key] = now;
    } else {
      window[key] = now;
      quota[key] = limit;
      quotaUsed[key] = 0;
    }

    return {
      windowStart: window[key],
      quota: quota[key],
      quotaUsed: quotaUsed[key]
    };
  }

  return {
    allow(key: string, nowMs: number): boolean {
      const window = getOrCreateWindow(key);
      if (nowMs < window.windowStart) {
        return false;
      }

      // Check boundary reset
      if (nowMs - window.windowStart >= windowMs) {
        window.quota = limit;
        window.quotaUsed = 0;
      }

      return window.quotaUsed + 1 <= window.quota;
    },
    remaining(key: string, nowMs: number): number {
      const window = getOrCreateWindow(key);
      let remaining;

      if (nowMs < window.windowStart) {
        // Time travel: reset to beginning of window
        remaining = window.quota;
        window.quotaUsed = 0;
      } else {
        remaining = window.quota - window.quotaUsed;
      }

      remaining = Math.max(remaining, 0);

      return remaining;
    },
    reset(key: string): void {
      if (!key) return;
      delete window[key];
      delete quota[key];
      delete quotaUsed[key];
    }
  };
}
