function createEventEmitter<T extends { [key: string]: (...args: any[]) => any }>(
  eventTypes: T
) {
  type Listener<T extends any[]> = (...args: T) => any;
  type OneTimeListener<T extends any[]> = (...args: T) => boolean;

  const listeners = new Map<keyof T, Array<Listener<...T[keyof T]> | OneTimeListener<...T[keyof T]>>>();

  function register<E extends keyof T>(eventName: E, listener: List | OneTimeListener<...T[E]>) {
    const eventListeners = listeners.get(eventName) || [];
    listeners.set(eventName, [...eventListeners, listener]);
  }

  function remove<E extends keyof T>(eventName: E, listener: Listener<...T[E]> | OneTimeListener<...T[E]>) {
    if (!listeners.has(eventName)) return;

    const eventListeners = listeners.get(eventName) as Array<Listener<...T[keyof T]> | OneTimeListener<...T[keyof T]>>;
    listeners.set(
      eventName,
      [...eventListeners].filter((l) => l !== listener)
    );
  }

  function emit<E extends keyof T>(eventName: E, ...args: T[E]) {
    if (!listeners.has(eventName)) return [];

    const eventListeners = listeners.get(eventName) as Array<Listener<...T[keyof T]> | OneTimeListener<...T[keyof T]>>;
    const results = [];

    for (const listener of eventListeners) {
      const result = listener(...args);
      results.push(result);
      if (typeof result === 'boolean' && result) {
        remove(eventName, listener);
      }
    }

    return results;
  }

  return { on: register as any, off: remove, emit };
}
