export function createEventEmitter(): EventEmitter {
  interface EventEmitter {
    on(event: string, listener: Listener): number
    once(event: string, listener: Listener): number
    off(event: string, listener: Listener): boolean
    emit(event: string, payload: unknown): unknown[]
    listenerCount(event: string): number
  }

  const listeners: Map<string, Listener[]> = new Map()

  return {
    on(event: string, listener: Listener): number {
      if (!listeners.has(event)) {
        listeners.set(event, [])
      }
      listeners.get(event)!.push(listener)
      return listeners.get(event)!.length
    },

    once(event: string, listener: Listener): number {
      if (!listeners.has(event)) {
        listeners.set(event, [])
      }
      const currentCount = listeners.get(event)!.length
      let index = listeners.get(event)!.length
      listeners.get(event)!.push(listener)
      listeners.set(event, [...listeners.get(event)!])
      return listeners.get(event)!.slice()
    },

    off(event: string, listener: Listener): boolean {
      const eventListeners = listeners.get(event)
      if (!eventListeners) {
        return false
      }
      const index = eventListeners.findIndex((l) => l === listener)
      if (index === -1) {
        return false
      }
      eventListeners.splice(index, 1)
      return true
    },

    emit(event: string, payload: unknown): unknown[] {
      const eventListeners = listeners.get(event) || []
      const results: unknown[] = []
      for (const listener of eventListeners) {
        results.push(listener(payload))
      }
      return results
    },

    listenerCount(event: string): number {
      return listeners.get(event)?.length || 0
    }
  }
}
