type RateLimiterOpts = {
  maxRequests: number;
  windowMs: number;
};

type RequestState = {
  lastWindowStartMs: number;
  requestCount: number;
};

type RateLimiter = {
  acquire: (key: string, nowMs?: number) => boolean;
  reset: (key: string) => void;
  getRemaining: (key: string, nowMs?: number) => number;
};

function createRateLimiter(opts: RateLimiterOpts): RateLimiter {
  const quotaMap = new Map<string, RequestState>();

  const acquire = (key: string, nowMs: number = Date.now()): boolean => {
    const state = quotaMap.get(key);

    if (!state) {
      quotaMap.set(key, { lastWindowStartMs: nowMs, requestCount: 0 });
      return true;
    }

    const { lastWindowStartMs, requestCount } = state;

    if (nowMs === lastWindowStartMs) {
      if (requestCount >= opts.maxRequests) {
        return false;
      }
      state.requestCount = requestCount + 1;
      return true;
    }

    if (nowMs - lastWindowStartMs >= opts.windowMs) {
      const remaining = opts.maxRequests - requestCount;
      if (remaining <= 0) {
        return false;
      }
      state.requestCount = requestCount + 1;
      return true;
    }

    if (requestCount < opts.maxRequests) {
      state.requestCount = requestCount + 1;
      return true;
    }

    return false;
  };

  const reset = (key: string) => {
    quotaMap.delete(key);
  };

  const getRemaining = (key: string, nowMs: number = Date.now()): number => {
    const state = quotaMap.get(key);

    if (!state) {
      return opts.maxRequests;
    }

    const { lastWindowStartMs, requestCount } = state;

    let currentWindowStartMs = lastWindowStartMs;
    if (nowMs - lastWindowStartMs >= opts.windowMs) {
      currentWindowStartMs = nowMs;
      quotaMap.set(key, { lastWindowStartMs: nowMs, requestCount: 0 });
    }

    const remaining = opts.maxRequests - requestCount;

    if (nowMs === lastWindowStartMs) {
      return remaining > 0 ? remaining : 0;
    }

    return remaining;
  };

  return { acquire, reset, getRemaining };
}

export { createRateLimiter };
