interface RateLimiter {
  allow(key: string, nowMs: number): boolean
  remaining(key: string, nowMs: number): number
  reset(key: string): void
}

declare const RATE_LIMIT: number
declare const RATE_WINDOW_MS: number

const RATE_LIMIT = 3
const RATE_WINDOW_MS = 1000

interface RateLimiterState {
  windowStart: number
  requestCount: number
}

declare global {
  var _rateLimiterState: Map<string, RateLimiterState>
}

global._rateLimiterState = new Map<string, RateLimiterState>()

export function createRateLimiter(): RateLimiter {
  return {
    allow(key: string, nowMs: number): boolean {
      let state = global._rateLimiterState.get(key)

      if (!state) {
        state = { windowStart: nowMs, requestCount: 0 }
        global._rateLimiterState.set(key, state)
      }

      // Check if new window should start
      const windowStart = state.windowStart
      if (nowMs - windowStart >= RATE_WINDOW_MS) {
        state.windowStart = nowMs
        state.requestCount = 0
      }

      if (state.requestCount < RATE_LIMIT) {
        state.requestCount++
        return true
      }

      return false
    },

    remaining(key: string, nowMs: number): number {
      let state = global._rateLimiterState.get(key)

      if (!state) {
        return RATE_LIMIT
      }

      const windowStart = state.windowStart
      if (nowMs - windowStart >= RATE_WINDOW_MS) {
        state.windowStart = nowMs
        state.requestCount = 0
      }

      return Math.max(0, RATE_LIMIT - state.requestCount)
    },

    reset(key: string): void {
      global._rateLimiterState.delete(key)
    }
  }
}

export type { RateLimiter }
