interface Entry {
  key: string
  value: unknown
  timestamp: number
  ttlMs: number
  expiresAt: number
}

class TtlCache {
  private entries: Map<string, Entry> = new Map()

  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
    const ttl = ttlMs ?? 1000
    this.entries.set(key, {
      key,
      value,
      timestamp: nowMs,
      ttlMs,
      expiresAt: nowMs + ttl
    })
  }

  get(key: string, nowMs: number): unknown {
    const entry = this.entries.get(key)
    if (!entry) {
      return undefined
    }
    if (nowMs >= entry.expiresAt) {
      this.entries.delete(key)
      return undefined
    }
    return entry.value
  }

  has(key: string, nowMs: number): boolean {
    const entry = this.entries.get(key)
    if (!entry) {
      return false
    }
    if (nowMs >= entry.expiresAt) {
      this.entries.delete(key)
      return false
    }
    return true
  }

  delete(key: string): boolean {
    if (this.entries.delete(key)) {
      return true
    }
    return false
  }

  size(nowMs: number): number {
    const count = new Map()
    for (const entry of this.entries.values()) {
      if (nowMs < entry.expiresAt) {
        count.set(entry.key, true)
      }
    }
    return count.size
  }

  clear(): void {
    this.entries.clear()
  }
}

export function createTtlCache(): TtlCache {
  return new TtlCache()
}
